import{_ as e,o as l,c as t,a2 as i}from"./chunks/framework.BXA5Pi9t.js";const p=JSON.parse('{"title":"Ceph Orchestrator Meeting 2021-08-10","description":"","frontmatter":{"title":"Ceph Orchestrator Meeting 2021-08-10","date":"2021-08-10T00:00:00.000Z","updated":"2021-08-21T00:00:00.000Z","tags":["Ceph","Orchestrator","Rook","CI/CD","Integration Testing"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2021/Ceph_Orchestrator_Meeting_2021-08-10.md","filePath":"posts/2021/Ceph_Orchestrator_Meeting_2021-08-10.md","lastUpdated":1780460162000}'),r={name:"posts/2021/Ceph_Orchestrator_Meeting_2021-08-10.md"};function o(n,a,h,s,u,c){return l(),t("div",null,[...a[0]||(a[0]=[i('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="会议主题-orchestrator-会议" tabindex="-1">会议主题：Orchestrator 会议 <a class="header-anchor" href="#会议主题-orchestrator-会议" aria-label="Permalink to &quot;会议主题：Orchestrator 会议&quot;">​</a></h4><h4 id="日期-2021年8月10日" tabindex="-1">日期：2021年8月10日 <a class="header-anchor" href="#日期-2021年8月10日" aria-label="Permalink to &quot;日期：2021年8月10日&quot;">​</a></h4><h4 id="参会人员-具体人员名单" tabindex="-1">参会人员：[具体人员名单] <a class="header-anchor" href="#参会人员-具体人员名单" aria-label="Permalink to &quot;参会人员：[具体人员名单]&quot;">​</a></h4><h4 id="主要议题" tabindex="-1">主要议题： <a class="header-anchor" href="#主要议题" aria-label="Permalink to &quot;主要议题：&quot;">​</a></h4><ol><li><p><strong>Rook CI 中 Manager Rook 模块的测试</strong></p><ul><li>讨论了在 Rook CI 中对 Manager Rook 模块的测试方法，包括使用 Kubeadm、Minikube、Kcli 等工具创建固定集群。</li><li>强调了集成测试的重要性，特别是在自动检测 Rook 项目中的潜在问题。</li><li>讨论了未来测试的改进方向，特别是关于 OSD 的管理和创建。</li></ul></li><li><p><strong>重置设计设置 OC Flex</strong></p><ul><li>讨论了在重启 OSD 时是否应设置 noout 标志。</li><li>确认了当前的做法是在维护模式下设置 noout，并在一定时间后重置。</li></ul></li><li><p><strong>存储私钥和 YAML 规范</strong></p><ul><li>讨论了在 YAML 规范中存储私钥的问题，特别是在使用 GitHub 存储 YAML 文件时。</li><li>提出了改进的必要性，但认为这不是最高优先级。</li></ul></li><li><p><strong>区域和区域组创建</strong></p><ul><li>讨论了在 Orchestrator 中创建区域和区域组的问题。</li><li>确认了需要引入 YAML 文档来简化这一过程。</li></ul></li><li><p><strong>本地存储操作符讨论</strong></p><ul><li>讨论了本地存储操作符的需求和设计。</li><li>提出了关于静态和动态存储供应的讨论，以及是否需要创建新的操作符。</li></ul></li></ol><h4 id="决定事项" tabindex="-1">决定事项： <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项：&quot;">​</a></h4><ul><li>确认了在 Rook 项目中集成测试的重要性，并计划改进 OSD 的管理和创建。</li><li>确认了在维护模式下设置 noout 的做法，并在一定时间后重置。</li><li>提出了改进存储私钥的方法，但认为这不是最高优先级。</li><li>确认了需要引入 YAML 文档来简化区域和区域组的创建。</li><li>提出了关于本地存储操作符的需求和设计，并决定是否需要创建新的操作符。</li></ul><h4 id="后续行动计划" tabindex="-1">后续行动计划： <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划：&quot;">​</a></h4><ul><li>继续改进 Rook 项目中的集成测试，特别是关于 OSD 的管理和创建。</li><li>研究改进存储私钥的方法，并评估其优先级。</li><li>引入 YAML 文档来简化区域和区域组的创建。</li><li>进一步讨论本地存储操作符的需求和设计，并决定是否需要创建新的操作符。</li></ul><h4 id="其他事项" tabindex="-1">其他事项： <a class="header-anchor" href="#其他事项" aria-label="Permalink to &quot;其他事项：&quot;">​</a></h4><ul><li>讨论了 Python 版本兼容性问题，并计划解决相关测试失败的问题。</li></ul><h4 id="会议结束" tabindex="-1">会议结束： <a class="header-anchor" href="#会议结束" aria-label="Permalink to &quot;会议结束：&quot;">​</a></h4><ul><li>会议在讨论完所有议题后结束，并安排了下次会议的时间。</li></ul>',14)])])}const _=e(r,[["render",o]]);export{p as __pageData,_ as default};
